#include "FontDevice.hpp"
#include "FileResources.hpp"
#include "Platform.hpp"
#include <ft2build.h>
#include FT_FREETYPE_H
#include FT_BITMAP_H
#include <cmath>
#include <map>
#ifdef __SWITCH__
#include <switch.h>
#endif
namespace th075::sdl {
namespace {
#include "cp932_table.inc" // generated by scripts/gen_cp932.py: cp932_map[65536]
}
struct FontDevice::Impl {
 struct Glyph {u16 width=0,height=0;i16 left=0,top=0;std::vector<u8> coverage;bool done=false;};
 FT_Library ft=nullptr;FT_Face face=nullptr;std::vector<u8> file;u32 size=0;i32 ascent=0;bool ms_metrics=false;std::string name;
 std::map<std::pair<u16,u16>,Glyph> cache;
 ~Impl(){if(face)FT_Done_Face(face);if(ft)FT_Done_FreeType(ft);}
 bool open(const std::string& path){if(!host::read_file(path,file,64*1024*1024))return false;if(FT_New_Memory_Face(ft,file.data(),FT_Long(file.size()),0,&face)){face=nullptr;file.clear();return false;}name=path;return true;}
 bool select(u32 height){
  if(size==height)return true;
  // Positive CreateFont heights are cell heights; MS Gothic's cell is its em,
  // so FreeType's CELL request matches GDI. Other faces are sized by em with
  // the baseline at MS Gothic's ascent (220/256 em).
  FT_Size_RequestRec request{ms_metrics?FT_SIZE_REQUEST_TYPE_CELL:FT_SIZE_REQUEST_TYPE_NOMINAL,0,FT_Long(height)*64,0,0};if(FT_Request_Size(face,&request))return false;
  ascent=ms_metrics?i32(std::lround(face->size->metrics.ascender/64.0)):i32(std::lround(height*220.0/256.0));size=height;return true;
 }
 const Glyph& render(u16 height,u16 code){
  auto& g=cache[{height,code}];if(g.done||!select(height))return g;g.done=true;   // blank or missing glyphs are kept too
  const u16 unicode=cp932_map[code];if(unicode==0x30fb&&code!=0x8145)return g;
  const FT_UInt index=FT_Get_Char_Index(face,unicode);if(!index||FT_Load_Glyph(face,index,FT_LOAD_DEFAULT|FT_LOAD_TARGET_NORMAL))return g;
  auto* slot=face->glyph;if(slot->format!=FT_GLYPH_FORMAT_BITMAP&&FT_Render_Glyph(slot,FT_RENDER_MODE_NORMAL))return g;
  FT_Bitmap gray;FT_Bitmap_Init(&gray);const bool converted=slot->bitmap.pixel_mode!=FT_PIXEL_MODE_GRAY;
  if(converted&&FT_Bitmap_Convert(ft,&slot->bitmap,&gray,1)){FT_Bitmap_Done(ft,&gray);return g;}
  const FT_Bitmap& b=converted?gray:slot->bitmap;const u32 levels=converted?u32(gray.num_grays):256;
  g.width=u16(std::min<u32>(b.width,256));g.height=u16(std::min<u32>(b.rows,256));g.left=i16(slot->bitmap_left);g.top=i16(ascent-slot->bitmap_top);
  // GGO_GRAY4_BITMAP: 17 levels, 0..16.
  g.coverage.resize(std::size_t(g.width)*g.height);
  for(u32 y=0;y<g.height;++y)for(u32 x=0;x<g.width;++x){const u32 v=b.buffer[y*b.pitch+x];g.coverage[y*g.width+x]=u8((v*16+(levels-1)/2)/(levels-1));}
  FT_Bitmap_Done(ft,&gray);return g;
 }
};
FontDevice::FontDevice(GraphicsDevice& g):graphics(g),impl(std::make_unique<Impl>()){}
FontDevice::~FontDevice()=default;
bool FontDevice::initialize(){
 std::vector<u8> b;
 if(host::read_file(host::paths().data_file("original-glyphs.bin"),b,256*1024*1024)&&bank.load(b.data(),b.size())){host::log("fonts: original GDI glyph bank");return true;}
 auto& a=*impl;if(FT_Init_FreeType(&a.ft)){error="FreeType unavailable";return false;}
 for(const char* name:{"msgothic.ttc","MSGOTHIC.TTC","msgothic.ttf"})if(a.open(host::paths().data_file(name)))break;
#ifdef __SWITCH__
 if(!a.face){PlFontData font{};if(R_SUCCEEDED(plInitialize(PlServiceType_User))&&R_SUCCEEDED(plGetSharedFontByType(&font,PlSharedFontType_Standard))&&font.address&&!FT_New_Memory_Face(a.ft,static_cast<const FT_Byte*>(font.address),FT_Long(font.size),0,&a.face))a.name="Switch shared font";}
#endif
 if(!a.face){error="No Japanese font: put msgothic.ttc (C:\\Windows\\Fonts) next to th075.dat";return false;}
 a.ms_metrics=FT_IS_SFNT(a.face)&&a.face->ascender-a.face->descender==a.face->units_per_EM;
 host::log("fonts: %s (%s metrics), glyphs rendered on first use",a.name.c_str(),a.ms_metrics?"MS":"em");
 bank.source=[this](u16 height,u16 code,GlyphOutline& out){if(code>=0xff00)code&=255;const auto& g=impl->render(height,code);out={g.width,g.height,g.width,g.left,g.top,g.coverage.data()};return true;};
 return true;
}
u32 FontDevice::create(const std::string& text,const TextRasterOptions& options){const u32 handle=graphics.create_surface(options.width,options.height);if(!handle)return 0;if(!write(handle,text,options)){graphics.destroy(handle);return 0;}return handle;}
bool FontDevice::raster(const std::string& text,const TextRasterOptions& options,std::vector<u8>& pixels){TextRaster raster(bank);if(options.bytesPerPixel!=4||!raster.render(text,options,pixels)){error=raster.error;return false;}return true;}
bool FontDevice::write(u32 handle,const std::string& text,const TextRasterOptions& options){std::vector<u8> pixels;if(!raster(text,options,pixels))return false;if(!graphics.update_pixels(handle,pixels.data(),u32(pixels.size()))){error="Unable to update text surface";return false;}return true;}
}
